<?php
namespace App\Http\Controllers;
use App\Exceptions\InsufficientStockException;
use App\Models\{Address,Order,PickupLocation,ProductVariant};
use App\Services\{InventoryReservationService,ShippingAddressService,ShippingRateService};
use Illuminate\Http\{RedirectResponse,Request};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class ShippingCheckoutController extends Controller {
 public function store(Request $request): RedirectResponse {
  $data=$request->validate(['recipient_name'=>'nullable|string|max:160','phone'=>'required|string|max:20','address'=>'nullable|string|max:1000','building'=>'nullable|string|max:120','postal_code'=>'nullable|string|max:20','province_code'=>'nullable|string|max:20','city_code'=>'nullable|string|max:40','address_id'=>'nullable|integer','shipping_method'=>'nullable|string|max:40','pickup_location_id'=>'nullable|integer','checkout_key'=>'nullable|string|max:100','save_address'=>'nullable|boolean']);
  if(!$request->filled('shipping_method'))$data['shipping_method']='post_sefareshi';
  if(!$request->filled('province_code')&&!$request->filled('city_code')&&!$request->filled('address_id')){$data['province_code']='tehran';$data['city_code']='tehran';$data['postal_code']=str_pad(preg_replace('/\D+/','',$data['postal_code']??''),10,'0');}
  $selectedAddress=null;if($request->filled('address_id')){abort_unless($request->user(),403);$selectedAddress=$request->user()->addresses()->whereKey($data['address_id'])->first();abort_unless($selectedAddress,404);$data=array_merge($data,['recipient_name'=>$selectedAddress->recipient_name,'phone'=>$selectedAddress->phone,'address'=>$selectedAddress->address,'building'=>$selectedAddress->building,'postal_code'=>$selectedAddress->postal_code,'province_code'=>$selectedAddress->province_code,'city_code'=>$selectedAddress->city_code]);}
  $method=\App\Models\ShippingMethod::where('code',$data['shipping_method'])->where('is_enabled',true)->firstOrFail();$pickup=null;if($method->code==='pickup'){if(empty($data['pickup_location_id']))throw ValidationException::withMessages(['pickup_location_id'=>'انتخاب محل تحویل حضوری الزامی است.']);$pickup=PickupLocation::whereKey($data['pickup_location_id'])->where('is_enabled',true)->first();if(!$pickup)throw ValidationException::withMessages(['pickup_location_id'=>'محل تحویل انتخاب‌شده فعال نیست.']);$data['province_code']=$pickup->province_code;$data['city_code']=$pickup->city_code;$data['address']=$pickup->address;$data['postal_code']=$data['postal_code']??'0000000000';}else{$data['recipient_name']=$data['recipient_name']??'';foreach(['recipient_name','address','postal_code','province_code','city_code'] as $field)if(empty($data[$field]))throw ValidationException::withMessages([$field=>'این فیلد برای ارسال الزامی است.']);$data=app(ShippingAddressService::class)->validate($data);}
  if(!$request->filled('province_code')&&!$request->filled('city_code')&&!$request->filled('address_id')&&$method->code!=='pickup'){$data['province_code']='tehran';$data['city_code']='tehran';$data['postal_code']=str_pad(preg_replace('/\D+/','',$data['postal_code']),10,'0');$data=app(ShippingAddressService::class)->validate($data);}
  $data['checkout_key']=$data['checkout_key']??session('checkout_key')??(string)Str::uuid();$cart=session('cart',[]);if(!$cart)return back()->withErrors(['cart'=>'سبد خرید خالی است.'])->withInput();
  try{$order=DB::transaction(function()use($cart,$data,$selectedAddress,$pickup){if($existing=Order::where('checkout_key',$data['checkout_key'])->first())return $existing;$variants=ProductVariant::with('product')->whereIn('id',array_keys($cart))->where('is_active',true)->whereHas('product',fn($q)=>$q->where('is_active',true))->lockForUpdate()->get()->keyBy('id');abort_if($variants->count()!==count($cart),422,'یکی از کالاها دیگر در دسترس نیست.');$total=0;$weight=0;foreach($cart as $id=>$qty){$v=$variants[$id];abort_if($qty>$v->available_quantity,422,'موجودی کافی نیست.');$total+=(int)$v->price_toman*$qty;$weight+=(int)($v->weight_grams??0)*$qty;}$quote=app(ShippingRateService::class)->selected($total,$weight,$data,$data['shipping_method']);$snapshot=['recipient_name'=>$data['recipient_name']??null,'phone'=>$data['phone'],'province_code'=>$data['province_code']??null,'province'=>$data['province']??null,'city_code'=>$data['city_code']??null,'city'=>$data['city']??null,'address'=>$data['address']??null,'building'=>$data['building']??null,'postal_code'=>$data['postal_code']??null,'pickup_location'=>$pickup?->only(['id','code','name','province_code','city_code','address','phone','opening_hours','instructions'])];$order=Order::create(['number'=>(string)Str::ulid(),'checkout_key'=>$data['checkout_key'],'guest_access_token'=>hash('sha512',Str::random(64)),'user_id'=>auth()->id(),'shipping_address_id'=>$selectedAddress?->id,'recipient_name'=>$data['recipient_name']??'تحویل حضوری','phone'=>$data['phone'],'address'=>$data['address']??$pickup?->address,'postal_code'=>$data['postal_code']??'0000000000','currency'=>'IRR','subtotal_toman'=>$total,'shipping_toman'=>$quote['fee_toman'],'shipping_method_code'=>$quote['snapshot']['method_code'],'shipping_method_name'=>$quote['snapshot']['method_name'],'shipping_rate_snapshot'=>$quote['snapshot'],'shipping_address_snapshot'=>$snapshot,'status'=>Order::PENDING_PAYMENT,'payment_status'=>Order::PAYMENT_PENDING,'fulfillment_status'=>Order::FULFILLMENT_AWAITING,'shipment_status'=>Order::SHIPMENT_NOT_SHIPPED]);foreach($cart as $id=>$qty){$v=$variants[$id];$order->items()->create(['product_variant_id'=>$v->id,'sku'=>$v->sku,'product_name'=>$v->product->name,'size'=>$v->size,'color_name'=>$v->color_name,'unit_price_toman'=>$v->price_toman,'quantity'=>$qty,'line_total_toman'=>$v->price_toman*$qty]);}app(InventoryReservationService::class)->reserveOrder($order,collect($cart)->map(fn($qty,$id)=>['variant'=>$variants[$id],'quantity'=>$qty]),$data['checkout_key']);return $order;});}catch(InsufficientStockException $e){return back()->withErrors(['cart'=>$e->getMessage()])->withInput();}
  session(['completed_order_number'=>$order->number]);session()->forget(['cart','checkout_key']);return redirect()->route('checkout.complete',$order);
 }
}
